library(shiny)
library(tidyverse)
library(plotly)
library(DT)

set.seed(2026)
quarters <- c("Q1 (Jan-Mar)", "Q2 (Apr-Jun)", "Q3 (Jul-Sep)")
working_groups <- paste("Working Group", LETTERS[1:30])

wg_data <- expand.grid(Quarter = quarters, Group = working_groups) %>%
  filter(runif(n()) > 0.4) %>% 
  mutate(
    Category = "Working Groups",
    Participants = case_when(
      Quarter == "Q1 (Jan-Mar)" ~ sample(10:35, n(), replace = TRUE),
      Quarter == "Q2 (Apr-Jun)" ~ sample(15:45, n(), replace = TRUE),
      Quarter == "Q3 (Jul-Sep)" ~ sample(20:60, n(), replace = TRUE)
    )
  )

event_counts <- c(4, 7, 5)
event_data <- map_df(seq_along(quarters), function(i) {
  num_events <- event_counts[i]
  tibble(
    Quarter = quarters[i],
    Group = paste("Webinar", 1:num_events),
    Category = "Events & Webinars",
    Participants = sample(40:150, num_events, replace = TRUE)
  )
})

df_master <- bind_rows(wg_data, event_data)

ui <- fluidPage(
  titlePanel("2026 Engagement Analytics Dashboard"),
  sidebarLayout(
    sidebarPanel(
      textInput("search_term", "Search Group or Event:", value = ""),
      selectInput("quarter_select", "Filter Quarter:", choices = c("All Quarters", quarters), selected = "All Quarters"),
      checkboxGroupInput("category_select", "Category Filter:", choices = c("Working Groups", "Events & Webinars"), selected = c("Working Groups", "Events & Webinars"))
    ),
    mainPanel(
      wellPanel(
        fluidRow(
          column(4, 
            div(style = "background-color: #2c3e50; color: white; padding: 15px; border-radius: 5px; text-align: center;",
                h4("Total Participants"),
                h2(textOutput("total_participants"))
            )
          ),
          column(4, 
            div(style = "background-color: #8e44ad; color: white; padding: 15px; border-radius: 5px; text-align: center;",
                h4("Total Meetings"),
                h2(textOutput("total_meetings"))
            )
          ),
          column(4, 
            div(style = "background-color: #27ae60; color: white; padding: 15px; border-radius: 5px; text-align: center;",
                h4("Avg Attendance"),
                h2(textOutput("avg_attendance"))
            )
          )
        )
      ),
      tabsetPanel(
        tabPanel("Overview Charts", 
          br(),
          fluidRow(
            column(6, plotlyOutput("line_chart")),
            column(6, plotlyOutput("bar_chart"))
          ),
          br(),
          plotlyOutput("heatmap_chart")
        ),
        tabPanel("Data Table", br(), DTOutput("combined_table"))
      )
    )
  )
)

server <- function(input, output, session) {
  filtered_data <- reactive({
    data <- df_master
    if (input$search_term != "") {
      data <- data %>% filter(str_detect(Group, regex(input$search_term, ignore_case = TRUE)))
    }
    if (input$quarter_select != "All Quarters") {
      data <- data %>% filter(Quarter == input$quarter_select)
    }
    data <- data %>% filter(Category %in% input$category_select)
    return(data)
  })
  
  output$total_participants <- renderText({
    format(sum(filtered_data()$Participants), big.mark = ",")
  })
  
  output$total_meetings <- renderText({
    nrow(filtered_data())
  })
  
  output$avg_attendance <- renderText({
    if (nrow(filtered_data()) > 0) {
      round(mean(filtered_data()$Participants), 1)
    } else {
      0
    }
  })
  
  output$line_chart <- renderPlotly({
    trend_df <- filtered_data() %>%
      group_by(Quarter, Category) %>%
      summarise(Participants = sum(Participants), .groups = "drop")
    p <- ggplot(trend_df, aes(x = Quarter, y = Participants, group = Category, color = Category)) +
      geom_line(size = 1.2) + geom_point(size = 3) + theme_minimal() +
      labs(title = "Quarterly Growth Trend", x = "", y = "Participants")
    ggplotly(p)
  })
  
  output$bar_chart <- renderPlotly({
    p <- ggplot(filtered_data(), aes(x = Quarter, y = Participants, fill = Category)) +
      geom_col(position = "dodge") + theme_minimal() +
      labs(title = "Participant Reach Distribution", x = "", y = "Participants")
    ggplotly(p)
  })
  
  output$heatmap_chart <- renderPlotly({
    plot_ly(data = filtered_data(), x = ~Quarter, y = ~Group, z = ~Participants, type = "heatmap", colors = "Blues") %>%
      layout(title = "Meeting Cadence & Attendance Matrix", xaxis = list(title = "", tickangle = -45), yaxis = list(dtick = 1))
  })
  
  output$combined_table <- renderDT({
    datatable(filtered_data(), options = list(pageLength = 10))
  })
}

shinyApp(ui = ui, server = server)
